function runDebugAnswer(eventIdArg: string | undefined): void {
  const eventId = Number(eventIdArg);
  if (!eventIdArg || !Number.isInteger(eventId)) {
    process.stderr.write("Usage: grasp debug:answer <event-id>\n");
    process.exitCode = 1;
    return;
  }

  const db = openStore();
  try {
    const event = getEventById(db, eventId);
    if (!event) {
      process.stderr.write(`No event with id=${eventId} found in ${db.name}\n`);
      process.exitCode = 1;
      return;
    }

    const tags = markEventAnswered(db, eventId, {
      answerConcept: event.questionConcept ? "(debug:answer stub) understood" : null,
      answerInstance: event.questionInstance ? "(debug:answer stub) understood" : null,
    });

    process.stdout.write(
      [
        `Marked event id=${eventId} answered.`,
        tags.length > 0
          ? `concept_tags now answered: ${tags.join(", ")}`
          : "(this event had no linked concept_tags — nothing to mark)",
        "",
      ].join("\n")
    );
  } finally {
    db.close();
  }
}

function runDebugCapture(repoPathArg: string | undefined): void {
  if (!repoPathArg) {
    process.stderr.write("Usage: grasp debug:capture <repo-path>\n");
    process.exitCode = 1;
    return;
  }

  const adapter = new GitDiffAdapter(repoPathArg);
  const diff = adapter.checkForChanges();

  if (diff.files.length === 0) {
    process.stdout.write(`No changes detected in ${diff.repo}\n`);
    return;
  }

  const summaryLines = diff.files.map(
    (f) =>
      `  ${f.status.padEnd(8)} ${f.oldPath ? `${f.oldPath} -> ` : ""}${f.path}  (+${f.insertions}/-${f.deletions}, ${f.hunks.length} hunk${f.hunks.length === 1 ? "" : "s"})`
  );

  const { config } = loadConfig(diff.repo);
  const verdict = evaluateCapturedDiff(diff, config);
  const filterLines = verdict.passed
    ? [
        `PASSED — ${verdict.significantFiles.length} significant file(s), ${verdict.totalChangedLines} changed lines total (max single file: ${verdict.maxSingleFileChangedLines})`,
      ]
    : [`FILTERED — reason: ${verdict.reason}`];
  if (verdict.excludedFiles.length > 0) {
    filterLines.push(
      "  excluded:",
      ...verdict.excludedFiles.map((f) => `    ${f.path} (${f.reason})`)
    );
  }

  process.stdout.write(
    [
      `Captured diff for ${diff.repo} at ${diff.capturedAt}`,
      `${diff.files.length} file(s) changed:`,
      ...summaryLines,
      "",
      "--- Phase 4 filter verdict ---",
      ...filterLines,
      "",
      "--- full CapturedDiff object (JSON) ---",
      JSON.stringify(diff, null, 2),
      "",
    ].join("\n")
  );
}

function readStdin(): Promise<string> {
  return new Promise((resolve, reject) => {
    let data = "";
    process.stdin.setEncoding("utf-8");
    process.stdin.on("data", (chunk) => (data += chunk));
    process.stdin.on("end", () => resolve(data));
    process.stdin.on("error", reject);
  });
}

/**
 * "There's still a pending question for this session" message, shared by
 * the PreToolUse deny reason and the Stop systemMessage nudge so the two
 * don't drift into inconsistent wording.
 */
function pendingQuestionsMessage(count: number): string {
  return `${count} question${count === 1 ? "" : "s"} waiting — run \`grasp review\` to answer ${count === 1 ? "it" : "them"}.`;
}

/**
 * Brief §3.3's "cumulative session spend visible to the user, not just
 * logged" — see DECISIONS.md's "session-end cost summary" entry for why
 * this lives on `Stop` (the only channel a hook has to say anything at
 * all) and why 4 decimal places (real per-call costs are sub-cent; 2
 * decimals would round most of them to "$0.00" and hide the exact signal
 * the cap/summary exist to surface).
 */
function costSummaryMessage(costUsd: number): string {
  return `$${costUsd.toFixed(4)} spent generating comprehension questions this session so far.`;
}

/**
 * Claude Code hook entrypoint. Must NEVER throw, hang, or exit non-zero —
 * a hook that crashes would block the user's real Claude Code session
 * regardless of gateMode. Every failure mode below is caught and
 * swallowed rather than propagated. Hooks never render UI themselves (see
 * DECISIONS.md's TTY-access finding) — they only write state and, for
 * PreToolUse under hard-gate, emit the documented deny JSON; presentation
 * always happens in a separately-launched `grasp review`.
 */
async function runInternalHook(): Promise<void> {
export function markEventAnswered(
  db: Database.Database,
  eventId: number,
  answers: { answerConcept: string | null; answerInstance: string | null }
): string[] {
  const tags = getConceptTagsByEventId(db, eventId);

  const runInTransaction = db.transaction(() => {
    db.prepare(`UPDATE concept_tags SET answered = 1 WHERE event_id = ?`).run(eventId);
    db.prepare(`UPDATE events SET answer_concept = ?, answer_instance = ? WHERE id = ?`).run(
      answers.answerConcept,
      answers.answerInstance,
      eventId
    );
  });
  runInTransaction();

  return tags.map((t) => t.tag);
}

/**
 * Marks an event skipped. Per DECISIONS.md's "skip skips the whole event"
 * entry: the schema has one `skipped`/`skip_reason` pair per event, not
 * per sub-question, so this is all-or-nothing even for a "both" question —
 * there's no partial-skip state to represent.
 */
export function markEventSkipped(
  db: Database.Database,
  eventId: number,
  skipReason: string | null
): void {
  db.prepare(`UPDATE events SET skipped = 1, skip_reason = ? WHERE id = ?`).run(skipReason, eventId);
}

const PENDING_QUESTION_WHERE = `
  question_type IS NOT NULL
  AND skipped = 0
  AND answer_instance IS NULL
`;

/**
 * Every real (non-miss), unanswered, unskipped question across ALL repos —
 * deliberately global, matching the project's existing concept-tag
 * memoization precedent, not scoped to the current working directory's
 * repo. See DECISIONS.md's "grasp review query scope" entry for why.
 * `answer_instance IS NULL` alone is a reliable "not yet answered" check:
 * every real question (question_type "both" or "instance") always has a
 * non-null question_instance and gets it answered last in `review`'s
 * concept-then-instance sequence, so it's null iff the event is still
 * pending regardless of question_type.
 */
export function getPendingQuestions(db: Database.Database): EventRecord[] {
  const rows = db
    .prepare(`SELECT * FROM events WHERE ${PENDING_QUESTION_WHERE} ORDER BY timestamp ASC`)
    .all();
  return rows.map(fromEventRow);
}

/**
 * Same "pending question" definition, scoped to one Claude Code
 * `session_id` — what the `Stop` nudge uses (see DECISIONS.md's
 * "gate-check scope" entry): whether *this session's own* work has an
 * unanswered question outstanding, not whether the user has anything
 * pending anywhere. The nudge is informational only (never blocks), so it
 * intentionally counts everything regardless of age — see
 * `getBlockingPendingQuestionsForSession` below for the narrower,
 * age-limited definition the hard-gate check itself uses.
 */
export function getPendingQuestionsForSession(
  db: Database.Database,
  sessionId: string
): EventRecord[] {
  const rows = db
    .prepare(
      `SELECT * FROM events WHERE ${PENDING_QUESTION_WHERE} AND session_id = ? ORDER BY timestamp ASC`
    )
    .all(sessionId);
  return rows.map(fromEventRow);
}

/**
 * How old a pending question can be and still actively deny a tool call
 * under hard-gate mode. README/TESTING_GUIDE both document hard-gate as
 * scoped to "that specific session" and explicitly promise it "never
 * blocks you over something left over from a different day" — but a Claude
 * Code `session_id` can genuinely be resumed days or weeks later (e.g.
 * `claude --resume`), so `session_id` scoping alone doesn't actually
 * guarantee that. This is Grasp's own gap-filling choice (not settled by
 * the brief): 24 hours is a deliberately generous, simple "still basically
 * the same sitting" cutoff — long enough to never interrupt a same-day
 * session picked back up after a break, short enough that a session
 * abandoned and resumed on a different calendar day reliably falls outside
 * it. See DECISIONS.md's "Stale pending question cutoff" entry.
 */
export const HARD_GATE_MAX_AGE_MS = 24 * 60 * 60 * 1000;

/**
 * The narrower definition of "pending" the `PreToolUse` hard-gate check
 * uses: real, unanswered, unskipped questions for this session AND recent
 * enough (within `HARD_GATE_MAX_AGE_MS`) to still actively block. An old
 * question outside that window remains fully visible and answerable in
 * `grasp review` and still counts toward the `Stop` nudge
 * (`getPendingQuestionsForSession` above) — this function only narrows
 * what's allowed to DENY a tool call, never what's shown or answerable.
 */
export function getBlockingPendingQuestionsForSession(
  db: Database.Database,
  sessionId: string,
  now: Date = new Date()
): EventRecord[] {
  const cutoff = new Date(now.getTime() - HARD_GATE_MAX_AGE_MS).toISOString();
  const rows = db
    .prepare(
      `SELECT * FROM events WHERE ${PENDING_QUESTION_WHERE} AND session_id = ? AND timestamp >= ? ORDER BY timestamp ASC`
    )
    .all(sessionId, cutoff);
  return rows.map(fromEventRow);
}

